window.QUESTION_TOPICS = window.QUESTION_TOPICS || {};
window.QUESTION_TOPICS["content/06_tools_build_debug/05_runtime.md"] = [{"id":"content/06_tools_build_debug/05_runtime.md:b6e459e0a0f2c6c2:1","question":"<p>(L1, T) Что такое процесс в Linux?</p>\n","answer":"<p><strong>Ответ:</strong> Процесс — экземпляр исполнения с адресным пространством и системными ресурсами; Linux планирует его потоки как tasks.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L1","line":35},{"id":"content/06_tools_build_debug/05_runtime.md:323e940f22caace5:1","question":"<p>(L1, T) Что такое PID?</p>\n","answer":"<p><strong>Ответ:</strong> Идентификатор процесса в PID namespace; одно исполнение может иметь разные видимые PID в разных namespaces.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L1","line":41},{"id":"content/06_tools_build_debug/05_runtime.md:2e92b91e70fcd8d5:1","question":"<p>(L1, T) Чем процесс отличается от потока?</p>\n","answer":"<p><strong>Ответ:</strong> Потоки разделяют адресное пространство и ресурсы процесса; процессы обычно изолированы и общаются через IPC.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L1","line":47},{"id":"content/06_tools_build_debug/05_runtime.md:cfa968d3227f95fe:1","question":"<p>(L1, T) Что делает <code>fork()</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Создаёт дочерний процесс, продолжающий исполнение после вызова; в multithreaded child остаётся только вызывающий поток.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L1","line":53},{"id":"content/06_tools_build_debug/05_runtime.md:64c6e86b853aca5c:1","question":"<p>(L1, T) Что делает <code>exec()</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Семейство exec заменяет образ текущего процесса новой программой; успешный вызов не возвращается и сохраняет PID.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L1","line":59},{"id":"content/06_tools_build_debug/05_runtime.md:fa788ad58c4adb87:1","question":"<p>(L1, T) В чем разница между <code>fork()</code> и <code>exec()</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Fork создаёт процесс, exec заменяет программу существующего; это независимые операции.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L1","line":65},{"id":"content/06_tools_build_debug/05_runtime.md:86c226d51875b95f:1","question":"<p>(L1, T) Что получает дочерний процесс после <code>fork()</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Логическую копию памяти и унаследованные ресурсы с исключениями; fd ссылаются на те же open file descriptions.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L1","line":71},{"id":"content/06_tools_build_debug/05_runtime.md:e4ab04868bdc850a:1","question":"<p>(L1, T) Что происходит с адресным пространством при <code>fork()</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Адресные пространства становятся раздельными; Linux обычно откладывает копирование физических страниц через copy-on-write.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L1","line":77},{"id":"content/06_tools_build_debug/05_runtime.md:a217493f585fe72e:1","question":"<p>(L1, T) Что такое copy-on-write?</p>\n","answer":"<p><strong>Ответ:</strong> Общее read-only размещение страниц до записи; запись вызывает создание частной копии там, где это требуется.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L1","line":83},{"id":"content/06_tools_build_debug/05_runtime.md:45726555e2d2d32f:1","question":"<p>(L1, P) Какой return value у <code>fork()</code> в родителе и в дочернем процессе?</p>\n","answer":"<p><strong>Ответ:</strong> В child возвращает 0, в parent — PID child; при ошибке возвращает -1 и child не создаётся.</p>\n<p><strong>Пример:</strong> Схема развилки после fork:</p>\n<pre><code class=\"language-c\">pid_t child = fork();\nif (child == -1) {\n    /* Ошибка: обработать errno, child не создан. */\n} else if (child == 0) {\n    /* Child: минимальная подготовка, exec; при неудаче _exit(...). */\n} else {\n    /* Parent: сохранить child PID и позже собрать wait status. */\n}\n</code></pre>\n<p><strong>Типичная ошибка:</strong> Считать отрицательный return value веткой parent с созданным child.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L1","line":89},{"id":"content/06_tools_build_debug/05_runtime.md:b8dd65341a67e2cf:1","question":"<p>(L2, T) Почему часто используют связку <code>fork() + exec()</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Parent остаётся работать, а child подготавливает окружение/fd и заменяется внешней программой.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L2","line":113},{"id":"content/06_tools_build_debug/05_runtime.md:912286b3e650933c:1","question":"<p>(L2, T) Что происходит с открытыми file descriptors при <code>fork()</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Child наследует descriptors, ссылающиеся на те же open file descriptions: offsets и некоторые flags разделяются.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L2","line":119},{"id":"content/06_tools_build_debug/05_runtime.md:dd0326d54a43a887:1","question":"<p>(L2, T) Что происходит с file descriptors при <code>exec()</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Обычно сохраняются, кроме помеченных <code>FD_CLOEXEC</code>; это может случайно передать sockets и pipe ends новой программе.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L2","line":125},{"id":"content/06_tools_build_debug/05_runtime.md:69121e1e919a18f3:1","question":"<p>(L2, T) Что делает флаг <code>FD_CLOEXEC</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Предписывает закрыть descriptor при успешном exec; сам fork его не закрывает.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L2","line":131},{"id":"content/06_tools_build_debug/05_runtime.md:9fc24b28ffd28d4d:1","question":"<p>(L2, P) Как дождаться завершения дочернего процесса?</p>\n","answer":"<p><strong>Ответ:</strong> <code>waitpid(child_pid, &amp;status, 0)</code>; обработать EINTR и проверить возвращённый PID.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L2","line":137},{"id":"content/06_tools_build_debug/05_runtime.md:952262f695d22d5a:1","question":"<p>(L2, P) Как узнать exit code дочернего процесса?</p>\n","answer":"<p><strong>Ответ:</strong> Сначала <code>WIFEXITED(status)</code>, затем <code>WEXITSTATUS(status)</code>; signal termination проверяют через <code>WIFSIGNALED</code>/<code>WTERMSIG</code>.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L2","line":143},{"id":"content/06_tools_build_debug/05_runtime.md:5489edc52db8b012:1","question":"<p>(L2, D) Почему после <code>fork()</code> код “выполняется дважды”?</p>\n","answer":"<p><strong>Ответ:</strong> Parent и child продолжают после fork; ветвить поведение по return value. Унаследованные stdio buffers тоже могут дублировать вывод.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L2","line":149},{"id":"content/06_tools_build_debug/05_runtime.md:f400579cdc909a1e:1","question":"<p>(L2, D) Почему после <code>exec()</code> часть ожидаемой логики не выполняется?</p>\n","answer":"<p><strong>Ответ:</strong> Успешный exec не возвращается; код после вызова исполняется только при ошибке и должен обработать errno.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L2","line":155},{"id":"content/06_tools_build_debug/05_runtime.md:70c6454c46efab4c:1","question":"<p>(L2, T) Что происходит с памятью процесса после успешного <code>exec()</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Старые mappings заменяются новым образом: code, data, stack и runtime initialization новой программы.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L2","line":161},{"id":"content/06_tools_build_debug/05_runtime.md:048bebbc0efc4e8d:1","question":"<p>(L2, T) Чем <code>execl</code>, <code>execv</code>, <code>execvp</code>, <code>execve</code> отличаются друг от друга?</p>\n","answer":"<p><strong>Ответ:</strong> <code>l</code> принимает список аргументов, <code>v</code> — массив; <code>p</code> ищет PATH, <code>e</code> принимает environment. <code>execve</code> — базовый Linux syscall.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L2","line":167},{"id":"content/06_tools_build_debug/05_runtime.md:73dc18f10233a450:1","question":"<p>(L3, T) Почему <code>fork()</code> в многопоточном процессе опасен?</p>\n","answer":"<p><strong>Ответ:</strong> Child копирует состояние locks, но не потоки-владельцы; обращение к runtime/allocator может зависнуть.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L3","line":176},{"id":"content/06_tools_build_debug/05_runtime.md:4e7626024c813aa4:1","question":"<p>(L3, T) Какие ограничения есть после <code>fork()</code> до <code>exec()</code> в multithreaded программе?</p>\n","answer":"<p><strong>Ответ:</strong> До exec в child допустимы только async-signal-safe операции; сложную C++ логику следует вынести до fork или в новую программу.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L3","line":182},{"id":"content/06_tools_build_debug/05_runtime.md:a02e57b82ddaf260:1","question":"<p>(L3, T) Что такое async-signal-safe functions и почему это важно после <code>fork()</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Это функции, допустимые при прерывании обычного исполнения обработчиком; после multithreaded fork они избегают повреждённых lock states.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L3","line":188},{"id":"content/06_tools_build_debug/05_runtime.md:8112e232b25f0729:1","question":"<p>(L3, D) Почему процесс завис после <code>fork()</code> в приложении с mutex'ами?</p>\n","answer":"<p><strong>Ответ:</strong> Mutex мог остаться locked потоком, отсутствующим в child; проверить child stack и заменить схему на подходящий spawn/exec.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L3","line":194},{"id":"content/06_tools_build_debug/05_runtime.md:beb7e192647794de:1","question":"<p>(L3, T) Что такое zombie process?</p>\n","answer":"<p><strong>Ответ:</strong> Завершившийся child, чей exit status ещё не собран родителем; остаётся запись процесса, а не исполняющийся код.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L3","line":200},{"id":"content/06_tools_build_debug/05_runtime.md:ebba9d84c7058b61:1","question":"<p>(L3, T) Что такое orphan process?</p>\n","answer":"<p><strong>Ответ:</strong> Процесс с завершившимся parent; Linux передаёт его ближайшему child subreaper или namespace init.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L3","line":206},{"id":"content/06_tools_build_debug/05_runtime.md:4fb81b4742d49416:1","question":"<p>(L3, D) Как найти и объяснить появление zombie processes?</p>\n","answer":"<p><strong>Ответ:</strong> Посмотреть <code>ps -eo pid,ppid,stat,cmd</code>, найти Z и parent; исправлять отсутствие wait/reaping у владельца.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L3","line":212},{"id":"content/06_tools_build_debug/05_runtime.md:1a4ce5f0ec4a2a36:1","question":"<p>(L3, P) Как перенаправить stdin/stdout/stderr дочернего процесса перед <code>exec()</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Создать нужные fd, выполнить <code>dup2(fd, STDOUT_FILENO)</code> и аналогично для stdin/stderr; закрыть лишние ends перед exec.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L3","line":218},{"id":"content/06_tools_build_debug/05_runtime.md:2d4594705f94330f:1","question":"<p>(L3, P) Как реализовать запуск внешней команды с пайпом?</p>\n","answer":"<p><strong>Ответ:</strong> Создать pipe, fork, перенаправить child stdout в write end, закрыть лишние ends; parent читает и затем вызывает waitpid.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L3","line":224},{"id":"content/06_tools_build_debug/05_runtime.md:729cb581db81554a:1","question":"<p>(L3, D) Почему child process наследует “лишние” дескрипторы?</p>\n","answer":"<p><strong>Ответ:</strong> Не задан CLOEXEC либо child не закрыл ненужные fd; использовать atomic flags <code>O_CLOEXEC</code>/<code>SOCK_CLOEXEC</code> при создании.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L3","line":230},{"id":"content/06_tools_build_debug/05_runtime.md:9b071049459b2f99:1","question":"<p>(L4, S) Когда процессы лучше потоков для изоляции и надежности?</p>\n","answer":"<p><strong>Ответ:</strong> Когда нужны fault/resource/security boundaries; учитывать IPC, копирование данных и стоимость управления процессами.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L4","line":239},{"id":"content/06_tools_build_debug/05_runtime.md:130af0ca52dc2913:1","question":"<p>(L4, S) Как проектировать process supervision в Linux-сервисе?</p>\n","answer":"<p><strong>Ответ:</strong> Владелец запускает и reaps workers, ограничивает restart rate, передаёт shutdown и фиксирует exit reason.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L4","line":245},{"id":"content/06_tools_build_debug/05_runtime.md:a7f02e3cb9a54a48:1","question":"<p>(L4, D) Как расследовать редкие deadlock'и, связанные с <code>fork()</code> в большом C++ приложении?</p>\n","answer":"<p><strong>Ответ:</strong> Снять stacks parent/child, найти последний вызов до exec и lock owner; проверить atfork handlers и небезопасный child code.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L4","line":251},{"id":"content/06_tools_build_debug/05_runtime.md:f048a9b8c15f1d07:1","question":"<p>(L4, S) Как проектировать безопасный launcher/worker runtime на базе <code>fork/exec</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Явный список наследуемых fd, минимальный child path, контролируемые argv/env, deadlines и supervision; рассмотреть posix_spawn.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L4","line":257},{"id":"content/06_tools_build_debug/05_runtime.md:15acf09ca9f3c939:1","question":"<p>(L4, D) Как строить forensic-анализ проблем с process lifecycle в production?</p>\n","answer":"<p><strong>Ответ:</strong> Коррелировать PID/start time, exec/build ID, fd inheritance, signals и wait status; PID без времени старта может переиспользоваться.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">fork(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/execve.2.html\">execve(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/waitpid.2.html\">waitpid(2)</a></p>\n","group":"L4","line":263},{"id":"content/06_tools_build_debug/05_runtime.md:44ec605ba9db7826:1","question":"<p>(L1, T) Что такое поток исполнения?</p>\n","answer":"<p><strong>Ответ:</strong> Независимый поток исполнения с собственными registers/stack, разделяющий ресурсы процесса с соседними потоками.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L1","line":274},{"id":"content/06_tools_build_debug/05_runtime.md:ac32be9bfc077573:1","question":"<p>(L1, T) Что общее у потоков одного процесса?</p>\n","answer":"<p><strong>Ответ:</strong> Адресное пространство, globals, heap, descriptors и signal dispositions; доступ к общей памяти требует синхронизации.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L1","line":280},{"id":"content/06_tools_build_debug/05_runtime.md:654ec171e7f34a7d:1","question":"<p>(L1, T) Что у потоков раздельное?</p>\n","answer":"<p><strong>Ответ:</strong> Stack, registers, scheduling state, signal mask и thread-local storage; errno обычно thread-local.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L1","line":286},{"id":"content/06_tools_build_debug/05_runtime.md:aa48d6be41f258a0:1","question":"<p>(L1, T) Что такое <code>pthread</code>?</p>\n","answer":"<p><strong>Ответ:</strong> POSIX API потоков и синхронизации; pthread return codes часто возвращаются напрямую, а не через errno.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L1","line":292},{"id":"content/06_tools_build_debug/05_runtime.md:d7c6a9cbf6a9555c:1","question":"<p>(L1, P) Как создать поток через pthread API?</p>\n","answer":"<p><strong>Ответ:</strong> <code>pthread_create(&amp;thread, NULL, start, arg)</code> с функцией <code>void *start(void *)</code>; проверить return code и lifetime arg.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L1","line":298},{"id":"content/06_tools_build_debug/05_runtime.md:f2e413540d64465b:1","question":"<p>(L1, P) Как дождаться завершения потока?</p>\n","answer":"<p><strong>Ответ:</strong> <code>pthread_join(thread, &amp;result)</code> для joinable thread; не удерживать lock, который нужен завершающемуся потоку.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L1","line":304},{"id":"content/06_tools_build_debug/05_runtime.md:60760701307aedf6:1","question":"<p>(L1, T) Что такое joinable и detached thread?</p>\n","answer":"<p><strong>Ответ:</strong> Joinable требует join для сбора ресурсов; detached освобождает их автоматически после завершения и не допускает join.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L1","line":310},{"id":"content/06_tools_build_debug/05_runtime.md:a5a92d2d45cba18c:1","question":"<p>(L1, T) Что такое mutex?</p>\n","answer":"<p><strong>Ответ:</strong> Примитив взаимного исключения для согласованного доступа к состоянию; один lock должен защищать весь нужный invariant.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L1","line":316},{"id":"content/06_tools_build_debug/05_runtime.md:162b632d9f58ac4c:1","question":"<p>(L1, T) Зачем нужны condition variables?</p>\n","answer":"<p><strong>Ответ:</strong> Позволяют спать до изменения predicate, освобождая mutex на время ожидания; уведомление само по себе не хранит событие.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L1","line":322},{"id":"content/06_tools_build_debug/05_runtime.md:5faf69d1a5340bba:1","question":"<p>(L1, D) Почему многопоточный код сложнее однопоточного?</p>\n","answer":"<p><strong>Ответ:</strong> Возможны разные interleavings, lifetime races и memory visibility; успешный одиночный тест не охватывает все исполнения.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L1","line":328},{"id":"content/06_tools_build_debug/05_runtime.md:3c6a701ebf35ddb6:1","question":"<p>(L2, T) Что такое race condition?</p>\n","answer":"<p><strong>Ответ:</strong> Результат зависит от неуправляемого порядка конкурентных действий; race может существовать и при отсутствии data race.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L2","line":337},{"id":"content/06_tools_build_debug/05_runtime.md:446dc62cf6b74333:1","question":"<p>(L2, T) Чем race condition отличается от data race?</p>\n","answer":"<p><strong>Ответ:</strong> Data race — конфликтующие несинхронизированные обращения к памяти, хотя бы одно write; в C++ это UB. Race condition шире.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L2","line":343},{"id":"content/06_tools_build_debug/05_runtime.md:99c0fa447a5855fe:1","question":"<p>(L2, T) Что такое critical section?</p>\n","answer":"<p><strong>Ответ:</strong> Участок изменения/чтения общего invariant, требующий согласованного доступа участников.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L2","line":349},{"id":"content/06_tools_build_debug/05_runtime.md:5cd5f392ee9876b8:1","question":"<p>(L2, P) Как защитить shared data с помощью mutex?</p>\n","answer":"<p><strong>Ответ:</strong> Каждое обращение к защищённому invariant выполнять под тем же mutex; в C++ предпочитать scoped lock/RAII.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L2","line":355},{"id":"content/06_tools_build_debug/05_runtime.md:8d36abc6369d63fa:1","question":"<p>(L2, P) Как использовать condition variable для ожидания события?</p>\n","answer":"<p><strong>Ответ:</strong> Под mutex проверять predicate в цикле, вызывать wait, затем повторно проверять; producer изменяет состояние под тем же протоколом.</p>\n<p><strong>Пример:</strong> Фрагмент с заранее инициализированными mutex/cv; общий predicate всегда читается и меняется под mutex.</p>\n<pre><code class=\"language-c\">/* Consumer */\npthread_mutex_lock(&amp;mutex);\nwhile (!ready &amp;&amp; !stopping)\n    pthread_cond_wait(&amp;cv, &amp;mutex);\n/* Под lock забрать результат либо обработать stopping. */\npthread_mutex_unlock(&amp;mutex);\n\n/* Producer */\npthread_mutex_lock(&amp;mutex);\nready = 1;\npthread_cond_signal(&amp;cv);\npthread_mutex_unlock(&amp;mutex);\n</code></pre>\n<p>В production проверяют pthread return codes и отдельный shutdown path; boolean predicate не подходит для подсчёта нескольких сообщений.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L2","line":361},{"id":"content/06_tools_build_debug/05_runtime.md:53b96c91942bc9de:1","question":"<p>(L2, D) Почему “редко падающий” баг часто связан с потоками?</p>\n","answer":"<p><strong>Ответ:</strong> Вероятность дефекта зависит от interleaving; также исключают обычную memory corruption, не объявляя любой редкий crash race.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L2","line":386},{"id":"content/06_tools_build_debug/05_runtime.md:328fa6cd1379fdb8:1","question":"<p>(L2, D) Как возникает deadlock?</p>\n","answer":"<p><strong>Ответ:</strong> Участники циклически ждут ресурсы друг друга либо поток ждёт сам себя; помогают общий lock order и отсутствие wait под lock.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L2","line":392},{"id":"content/06_tools_build_debug/05_runtime.md:880f287ad71e6ee0:1","question":"<p>(L2, D) Как возникает livelock?</p>\n","answer":"<p><strong>Ответ:</strong> Потоки активны и реагируют друг на друга, но постоянно отменяют попытки, не продвигая полезную работу.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L2","line":398},{"id":"content/06_tools_build_debug/05_runtime.md:87c4cbf64e272f48:1","question":"<p>(L2, T) Что такое starvation?</p>\n","answer":"<p><strong>Ответ:</strong> Поток длительно не получает нужный ресурс/CPU, хотя другие участники продолжают работу.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L2","line":404},{"id":"content/06_tools_build_debug/05_runtime.md:f38ba40a92d71b00:1","question":"<p>(L2, T) Что такое thread-safe code?</p>\n","answer":"<p><strong>Ответ:</strong> Код сохраняет свой контракт при разрешённых конкурентных вызовах; нужно указать, для каких объектов и операций.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L2","line":410},{"id":"content/06_tools_build_debug/05_runtime.md:d055574681fe85af:1","question":"<p>(L3, T) Что такое memory ordering на практическом уровне?</p>\n","answer":"<p><strong>Ответ:</strong> Правила, определяющие наблюдаемость операций между потоками; mutex и release/acquire могут устанавливать happens-before.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L3","line":419},{"id":"content/06_tools_build_debug/05_runtime.md:392c23c1166f49d6:1","question":"<p>(L3, T) Почему “кажется, что работает” не доказывает корректность многопоточного кода?</p>\n","answer":"<p><strong>Ответ:</strong> UB и редкие interleavings могут не проявиться в текущем запуске; correctness требует аргумента о synchronization/lifetime.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L3","line":425},{"id":"content/06_tools_build_debug/05_runtime.md:d77a35111f5e29a6:1","question":"<p>(L3, D) Как расследовать race condition, которая плохо воспроизводится?</p>\n","answer":"<p><strong>Ответ:</strong> Использовать TSan, stress со seed, targeted delays и записи transitions; минимизировать сценарий, сохраняя конфликтующие обращения.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L3","line":431},{"id":"content/06_tools_build_debug/05_runtime.md:a4777379726e6f38:1","question":"<p>(L3, D) Как найти deadlock в pthread-based приложении?</p>\n","answer":"<p><strong>Ответ:</strong> Снять <code>thread apply all bt</code> в GDB, найти ожидания и owners; построить граф зависимостей locks/threads.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L3","line":437},{"id":"content/06_tools_build_debug/05_runtime.md:cbf56bd679c5f3e3:1","question":"<p>(L3, P) Как использовать thread sanitizer для pthread-кода?</p>\n","answer":"<p><strong>Ответ:</strong> Собрать и линковать с <code>-fsanitize=thread -g</code>, выполнить representative tests; ASan и TSan обычно запускают раздельно.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L3","line":443},{"id":"content/06_tools_build_debug/05_runtime.md:2ec9bfd5972adb2c:1","question":"<p>(L3, T) Почему неправильное владение mutex приводит к скрытым багам?</p>\n","answer":"<p><strong>Ответ:</strong> Unlock чужим потоком или несогласованный lifetime нарушает контракт mutex; normal mutex не предоставляет переносимой передачи ownership.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L3","line":449},{"id":"content/06_tools_build_debug/05_runtime.md:654025a3209b7751:1","question":"<p>(L3, D) Как отличить contention от настоящего deadlock?</p>\n","answer":"<p><strong>Ответ:</strong> При contention progress сохраняется после освобождения; при deadlock есть постоянная зависимость без допустимого продвижения.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L3","line":455},{"id":"content/06_tools_build_debug/05_runtime.md:653550399988b9d7:1","question":"<p>(L3, T) Что такое spurious wakeup и как правильно писать цикл ожидания?</p>\n","answer":"<p><strong>Ответ:</strong> Wait может вернуться без истинного условия; писать <code>while (!ready) pthread_cond_wait(&amp;cv, &amp;mutex)</code> с predicate под mutex.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L3","line":461},{"id":"content/06_tools_build_debug/05_runtime.md:af16c738fd1aca23:1","question":"<p>(L3, D) Почему condition variable без predicate — опасна?</p>\n","answer":"<p><strong>Ответ:</strong> Уведомление может произойти до wait, а wakeup быть spurious; только состояние predicate определяет возможность продолжать.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L3","line":467},{"id":"content/06_tools_build_debug/05_runtime.md:347cbc9aecd7e1a8:1","question":"<p>(L3, S) Когда использовать pthread API напрямую, а когда std::thread/std::mutex?</p>\n","answer":"<p><strong>Ответ:</strong> Стандартные C++ wrappers удобнее для переносимости/RAII; pthread нужен для специфических POSIX attributes и интеграции.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L3","line":473},{"id":"content/06_tools_build_debug/05_runtime.md:98656f5dd53010c5:1","question":"<p>(L4, S) Как проектировать многопоточную архитектуру, уменьшающую число shared-state ошибок?</p>\n","answer":"<p><strong>Ответ:</strong> Ограничивать shared mutable state, назначать owners, использовать queues и immutable snapshots, документировать shutdown/lifetime.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L4","line":482},{"id":"content/06_tools_build_debug/05_runtime.md:032ffe7e353f38e3:1","question":"<p>(L4, S) Как выбирать между thread-per-request, thread pool, actor/event-loop моделью?</p>\n","answer":"<p><strong>Ответ:</strong> Выбирать по concurrency, blocking cost и latency budget; event loop требует неблокирующих handlers, pool — ограниченной очереди.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L4","line":488},{"id":"content/06_tools_build_debug/05_runtime.md:41bc12315904f05e:1","question":"<p>(L4, D) Как расследовать latency spikes, вызванные lock contention?</p>\n","answer":"<p><strong>Ответ:</strong> Измерить lock wait/hold time, queue depth и stacks; долгий holder или oversubscription могут давать хвосты.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L4","line":494},{"id":"content/06_tools_build_debug/05_runtime.md:e954bc760c47bee2:1","question":"<p>(L4, S) Как формализовать policy по mutex ordering и concurrency review?</p>\n","answer":"<p><strong>Ответ:</strong> Задать порядок locks, protected invariants и запрет blocking callbacks под lock; проверять исключения review и тестами.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L4","line":500},{"id":"content/06_tools_build_debug/05_runtime.md:a3a35341840e97f7:1","question":"<p>(L4, D) Как строить post-mortem анализ сложных concurrency incidents?</p>\n","answer":"<p><strong>Ответ:</strong> Сохранить traces, stacks, workload и timeline; восстановить нарушенный invariant и проверить исправление тем же interleaving.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L4","line":506},{"id":"content/06_tools_build_debug/05_runtime.md:dda69235805f0b65:1","question":"<p>(L1, T) Что такое race condition простыми словами?</p>\n","answer":"<p><strong>Ответ:</strong> Два участника действуют так, что результат зависит от случайного порядка, хотя программа ожидает определённый протокол.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L1","line":517},{"id":"content/06_tools_build_debug/05_runtime.md:1f46729a19b7bc54:1","question":"<p>(L1, T) Почему race condition может не проявляться на тестовой машине?</p>\n","answer":"<p><strong>Ответ:</strong> Иные cores, timings, compiler optimization и нагрузка меняют вероятность опасного порядка исполнения.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L1","line":523},{"id":"content/06_tools_build_debug/05_runtime.md:5876f2f9be0840d8:1","question":"<p>(L1, T) Как shared mutable state создает риск race condition?</p>\n","answer":"<p><strong>Ответ:</strong> Несогласованные read-modify-write и lifetime transitions позволяют видеть противоречивое состояние.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L1","line":529},{"id":"content/06_tools_build_debug/05_runtime.md:98553e8942d3f146:1","question":"<p>(L1, D) Какие типичные признаки race condition?</p>\n","answer":"<p><strong>Ответ:</strong> Редкие неверные значения, потерянные updates, hangs и use-after-free; каждый симптом требует подтверждения.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L1","line":535},{"id":"content/06_tools_build_debug/05_runtime.md:4f439c98ad2f5297:1","question":"<p>(L1, D) Почему добавление логов может “чинить” race temporarily?</p>\n","answer":"<p><strong>Ответ:</strong> Логи меняют timing, lock contention и memory layout, случайно скрывая опасное исполнение.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L1","line":541},{"id":"content/06_tools_build_debug/05_runtime.md:d8e901c24bc581b3:1","question":"<p>(L2, D) Как воспроизводить race condition?</p>\n","answer":"<p><strong>Ответ:</strong> Создать concurrency stress с управляемыми точками ожидания и seed; использовать TSan и проверку invariants.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L2","line":550},{"id":"content/06_tools_build_debug/05_runtime.md:bf9aeb78c0a3bfdc:1","question":"<p>(L2, D) Почему scheduler влияет на вероятность воспроизведения race?</p>\n","answer":"<p><strong>Ответ:</strong> Определяет моменты preemption и совместное исполнение; нельзя полагаться на наблюдаемый порядок одного scheduler run.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L2","line":556},{"id":"content/06_tools_build_debug/05_runtime.md:de34a123b1a02b67:1","question":"<p>(L2, D) Какие классы race condition бывают в C/C++?</p>\n","answer":"<p><strong>Ответ:</strong> Data races, check-then-act/TOCTOU, lifetime races и protocol races; atomic variables устраняют не все логические races.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L2","line":562},{"id":"content/06_tools_build_debug/05_runtime.md:ccdbca48b1f23b6a:1","question":"<p>(L2, P) Какие минимальные шаги для локализации race bug?</p>\n","answer":"<p><strong>Ответ:</strong> Зафиксировать invariant, конфликтующие действия и минимальный workload; собрать stack traces и synchronization evidence.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L2","line":568},{"id":"content/06_tools_build_debug/05_runtime.md:6c0af8370431ada6:1","question":"<p>(L2, D) Почему use-after-free часто имеет concurrency-корень?</p>\n","answer":"<p><strong>Ответ:</strong> Один поток освобождает объект, пока другой ещё использует pointer; нужен явный протокол продления lifetime.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L2","line":574},{"id":"content/06_tools_build_debug/05_runtime.md:ebd41577e4ee1c21:1","question":"<p>(L3, D) Как доказывать наличие race condition, а не просто подозревать ее?</p>\n","answer":"<p><strong>Ответ:</strong> Показать конфликтующие операции без happens-before либо воспроизводимое нарушение протокола; TSan report — полезное свидетельство.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L3","line":583},{"id":"content/06_tools_build_debug/05_runtime.md:cf29f17ebae42a26:1","question":"<p>(L3, D) Как отличить race от memory corruption иной природы?</p>\n","answer":"<p><strong>Ответ:</strong> Сопоставить TSan и ASan в отдельных сборках, проверить lifetime и межпоточный доступ; инструменты могут находить разные причины.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L3","line":589},{"id":"content/06_tools_build_debug/05_runtime.md:05fca116b3924d9f:1","question":"<p>(L3, D) Как race condition проявляется через невалидные инварианты?</p>\n","answer":"<p><strong>Ответ:</strong> Например, объект помечен готовым до завершения initialization; формулировка invariant помогает найти отсутствующую связь порядка.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L3","line":595},{"id":"content/06_tools_build_debug/05_runtime.md:a3a2593f0d7860ef:1","question":"<p>(L3, D) Почему lock-free/low-lock код повышает требования к инженерной дисциплине?</p>\n","answer":"<p><strong>Ответ:</strong> Нужно отдельно доказывать ordering, reclamation, ABA и progress guarantees; отсутствие mutex не означает простоту или скорость.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L3","line":601},{"id":"content/06_tools_build_debug/05_runtime.md:6516de6fa9af47c1:1","question":"<p>(L3, S) Какие design-подходы лучше всего снижают риск race condition?</p>\n","answer":"<p><strong>Ответ:</strong> Single ownership, message passing, immutable data и ограниченные критические секции уменьшают число допустимых состояний.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L3","line":607},{"id":"content/06_tools_build_debug/05_runtime.md:1ddab19b36b76a71:1","question":"<p>(L4, S) Как внедрить systematic concurrency testing в команду?</p>\n","answer":"<p><strong>Ответ:</strong> TSan jobs, deterministic hooks, stress/replay, обязательные lifecycle tests и review synchronization contracts.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L4","line":616},{"id":"content/06_tools_build_debug/05_runtime.md:7d9b9162cffdf2c5:1","question":"<p>(L4, D) Как расследовать race в distributed/IPC-heavy системе?</p>\n","answer":"<p><strong>Ответ:</strong> Коррелировать local thread traces и IPC IDs; различать in-process data race и нарушение distributed ordering/protocol.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L4","line":622},{"id":"content/06_tools_build_debug/05_runtime.md:c46981ab14796c34:1","question":"<p>(L4, S) Как выбирать допустимый уровень concurrency complexity в продукте?</p>\n","answer":"<p><strong>Ответ:</strong> Выбирать простейшую модель, достигающую SLO; более сложные atomics требуют доказанного bottleneck и компетенции сопровождения.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L4","line":628},{"id":"content/06_tools_build_debug/05_runtime.md:bf8025802a5305ff:1","question":"<p>(L4, S) Как учить команду мыслить через invariants, а не только через mutex'ы?</p>\n","answer":"<p><strong>Ответ:</strong> Для каждого состояния определить допустимые transitions, owner и условие публикации; mutex — средство реализации этих правил.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">pthreads(7)</a>; <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a></p>\n","group":"L4","line":634},{"id":"content/06_tools_build_debug/05_runtime.md:75a7e54853807b4a:1","question":"<p>(L4, D) Как документировать и triage'ить concurrency bugs на больших кодовых базах?</p>\n","answer":"<p><strong>Ответ:</strong> Записывать symptom, invariant, workload, race evidence, suspected owners и reproduction seed; severity отделять от воспроизводимости.</p>\n<pre><code>**Источник:** [pthreads(7)](https://man7.org/linux/man-pages/man7/pthreads.7.html); [Clang: ThreadSanitizer](https://clang.llvm.org/docs/ThreadSanitizer.html)\n</code></pre>\n<hr />\n","group":"L4","line":640},{"id":"content/06_tools_build_debug/05_runtime.md:9f98da25690b9e49:1","question":"<p>(L1, T) Что такое file descriptor?</p>\n","answer":"<p><strong>Ответ:</strong> Небольшое целое число, индексирующее запись таблицы descriptors процесса и ссылающееся на kernel resource.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L1","line":655},{"id":"content/06_tools_build_debug/05_runtime.md:a07e03e9e033b7c4:1","question":"<p>(L1, T) Какие стандартные file descriptors есть у процесса?</p>\n","answer":"<p><strong>Ответ:</strong> 0 — stdin, 1 — stdout, 2 — stderr; они могут быть закрыты или перенаправлены.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L1","line":661},{"id":"content/06_tools_build_debug/05_runtime.md:5ee022daf1a61123:1","question":"<p>(L1, T) Что возвращает <code>open()</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Неотрицательный fd при успехе, -1 при ошибке с errno; значение 0 является корректным descriptor.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L1","line":667},{"id":"content/06_tools_build_debug/05_runtime.md:d36be69c57526611:1","question":"<p>(L1, T) Чем file descriptor отличается от <code>FILE*</code>?</p>\n","answer":"<p><strong>Ответ:</strong> <code>FILE*</code> — библиотечный stdio object с buffering и состоянием; fd — системный handle. Их lifecycle нужно согласовать.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L1","line":673},{"id":"content/06_tools_build_debug/05_runtime.md:769539dc96233243:1","question":"<p>(L1, P) Как открыть файл через системный вызов?</p>\n","answer":"<p><strong>Ответ:</strong> <code>open(path, O_RDONLY | O_CLOEXEC)</code>; при -1 обработать errno. Для <code>O_CREAT</code> передать mode с учётом umask.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L1","line":679},{"id":"content/06_tools_build_debug/05_runtime.md:3fb66fbbead3030a:1","question":"<p>(L1, P) Как читать и писать через file descriptor?</p>\n","answer":"<p><strong>Ответ:</strong> Использовать <code>read</code>/<code>write</code>, проверять ssize_t, partial progress, EOF и errno; не считать один вызов полной передачей.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L1","line":685},{"id":"content/06_tools_build_debug/05_runtime.md:3c7c860e8ab838c3:1","question":"<p>(L1, T) Что делает <code>close()</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Освобождает descriptor; ресурс закрывается после исчезновения остальных ссылок. Не следует слепо повторять close при ошибке на Linux.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L1","line":691},{"id":"content/06_tools_build_debug/05_runtime.md:3932878c50987ce3:1","question":"<p>(L1, D) Что происходит, если забыть закрыть fd?</p>\n","answer":"<p><strong>Ответ:</strong> Descriptor и ресурс сохраняются до закрытия или завершения процесса; может закончиться лимит fd.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L1","line":697},{"id":"content/06_tools_build_debug/05_runtime.md:5ac315d37f47cb59:1","question":"<p>(L1, T) Что такое EOF на уровне <code>read()</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Для положительного requested count возврат 0 означает EOF; у socket это обычно orderly shutdown peer write side.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L1","line":703},{"id":"content/06_tools_build_debug/05_runtime.md:67ab10652464225a:1","question":"<p>(L1, D) Почему утечки file descriptors опасны для long-running процессов?</p>\n","answer":"<p><strong>Ответ:</strong> Расходуются descriptors и связанные kernel resources; новые accept/open начинают возвращать ошибки.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L1","line":709},{"id":"content/06_tools_build_debug/05_runtime.md:f806461f7ef15782:1","question":"<p>(L2, T) Что такое blocking vs non-blocking I/O?</p>\n","answer":"<p><strong>Ответ:</strong> Blocking может ждать готовности; nonblocking возвращает EAGAIN/EWOULDBLOCK, если операция сейчас потребовала бы ожидания.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L2","line":718},{"id":"content/06_tools_build_debug/05_runtime.md:47b54cc06327612c:1","question":"<p>(L2, T) Что делает <code>fcntl(..., O_NONBLOCK)</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Правильно: получить flags через <code>F_GETFL</code>, затем <code>F_SETFL</code> с <code>flags | O_NONBLOCK</code>; это file status flag.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L2","line":724},{"id":"content/06_tools_build_debug/05_runtime.md:bba05ff7dc4436a4:1","question":"<p>(L2, D) Почему <code>read()</code>/<code>write()</code> могут вернуть меньше байт, чем ожидалось?</p>\n","answer":"<p><strong>Ответ:</strong> Доступно меньше данных/места, вмешался сигнал или семантика устройства допускает short I/O; сохранять progress.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L2","line":730},{"id":"content/06_tools_build_debug/05_runtime.md:7933f1b5da9b4f35:1","question":"<p>(L2, T) Что такое <code>EINTR</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Ошибка прерывания операции signal handler; решение о повторе зависит от syscall и уже выполненной работы.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L2","line":736},{"id":"content/06_tools_build_debug/05_runtime.md:9b95b6b17394ebcb:1","question":"<p>(L2, D) Почему системный вызов может быть прерван сигналом?</p>\n","answer":"<p><strong>Ответ:</strong> Сигнал может прервать ожидание; SA_RESTART перезапускает только определённые операции, не любой syscall.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L2","line":742},{"id":"content/06_tools_build_debug/05_runtime.md:5459f55a50de1252:1","question":"<p>(L2, P) Как дублировать fd через <code>dup</code>/<code>dup2</code>?</p>\n","answer":"<p><strong>Ответ:</strong> <code>dup(fd)</code> создаёт новую ссылку; <code>dup2(fd, target)</code> атомарно заменяет target при успехе. Проверять ошибки.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L2","line":748},{"id":"content/06_tools_build_debug/05_runtime.md:ec2dfe2c07ed69a5:1","question":"<p>(L2, P) Как перенаправить stdout процесса в файл?</p>\n","answer":"<p><strong>Ответ:</strong> Открыть файл, выполнить <code>dup2(fd, STDOUT_FILENO)</code>, закрыть исходный fd, если он отличается от stdout.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L2","line":754},{"id":"content/06_tools_build_debug/05_runtime.md:aac63bcab9ad804a:1","question":"<p>(L2, T) Что такое pipe?</p>\n","answer":"<p><strong>Ответ:</strong> Однонаправленный byte stream с read/write ends; EOF возникает, когда закрыты все write ends и данные прочитаны.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L2","line":760},{"id":"content/06_tools_build_debug/05_runtime.md:ae1f5c41c1542a33:1","question":"<p>(L2, P) Как устроен IPC через pipe на базовом уровне?</p>\n","answer":"<p><strong>Ответ:</strong> Parent/child закрывают неиспользуемые ends, передают framed bytes через read/write и обрабатывают EOF/partial I/O.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L2","line":766},{"id":"content/06_tools_build_debug/05_runtime.md:461965a449337431:1","question":"<p>(L2, D) Как возникают “Too many open files”?</p>\n","answer":"<p><strong>Ответ:</strong> EMFILE означает лимит процесса; ENFILE — системный лимит открытых файлов. Сначала искать leak и нагрузку.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L2","line":772},{"id":"content/06_tools_build_debug/05_runtime.md:b0662c330764bf6d:1","question":"<p>(L3, T) Что такое open file description и чем он отличается от fd?</p>\n","answer":"<p><strong>Ответ:</strong> Open file description — kernel object состояния открытия; несколько fd могут ссылаться на один объект.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L3","line":781},{"id":"content/06_tools_build_debug/05_runtime.md:afefcf6d8a935291:1","question":"<p>(L3, T) Какие состояния разделяют duplicated descriptors?</p>\n","answer":"<p><strong>Ответ:</strong> Offset и file status flags вроде O_NONBLOCK; descriptor flags вроде FD_CLOEXEC задаются для каждого fd отдельно.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L3","line":787},{"id":"content/06_tools_build_debug/05_runtime.md:ff7df30fd71f58b1:1","question":"<p>(L3, D) Почему offset файла “неожиданно общий” между двумя fd?</p>\n","answer":"<p><strong>Ответ:</strong> Fd получены через dup/fork и ссылаются на одну open file description; для независимого offset нужно отдельное open или pread.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L3","line":793},{"id":"content/06_tools_build_debug/05_runtime.md:4aea513c88534911:1","question":"<p>(L3, D) Как расследовать fd leak в production?</p>\n","answer":"<p><strong>Ответ:</strong> Снимать количество и цели <code>/proc/PID/fd</code> во времени, сопоставлять open/close paths и request lifecycle.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L3","line":799},{"id":"content/06_tools_build_debug/05_runtime.md:f9f040c6bee0d883:1","question":"<p>(L3, P) Как смотреть открытые fd процесса через <code>/proc</code>?</p>\n","answer":"<p><strong>Ответ:</strong> <code>ls -l /proc/PID/fd</code>; детали доступны в <code>/proc/PID/fdinfo</code>, с учётом permissions и namespace.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L3","line":805},{"id":"content/06_tools_build_debug/05_runtime.md:0d34e2d28089af5c:1","question":"<p>(L3, D) Почему небезопасное наследование fd ломает дочерние процессы?</p>\n","answer":"<p><strong>Ответ:</strong> Child удерживает sockets/pipe ends, препятствует EOF и получает неожиданный доступ; CLOEXEC предотвращает передачу через exec.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L3","line":811},{"id":"content/06_tools_build_debug/05_runtime.md:90bf35767600eada:1","question":"<p>(L3, T) Что такое socket как file descriptor?</p>\n","answer":"<p><strong>Ответ:</strong> Descriptor указывает на socket endpoint; доступен обычным read/write и socket-specific API/options.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L3","line":817},{"id":"content/06_tools_build_debug/05_runtime.md:d5ebb18912ddf37f:1","question":"<p>(L3, D) Почему non-blocking I/O требует иного стиля обработки ошибок?</p>\n","answer":"<p><strong>Ответ:</strong> EAGAIN является штатным состоянием, partial I/O требует буферов и state machine, readiness — повторной проверки операции.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L3","line":823},{"id":"content/06_tools_build_debug/05_runtime.md:c88ea8486232e88e:1","question":"<p>(L3, P) Как анализировать readiness/event-driven код на fd?</p>\n","answer":"<p><strong>Ответ:</strong> Проследить регистрацию, событие, actual I/O result и изменение state; проверить EOF, errors, backpressure и generation handle.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L3","line":829},{"id":"content/06_tools_build_debug/05_runtime.md:90528d1aa73af5a8:1","question":"<p>(L3, S) Когда выбирать blocking модель, а когда event-driven?</p>\n","answer":"<p><strong>Ответ:</strong> Blocking проще для ограниченной concurrency; event-driven подходит многим ожидающим connections при bounded работе handlers.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L3","line":835},{"id":"content/06_tools_build_debug/05_runtime.md:11da1adc4af2b0b6:1","question":"<p>(L4, S) Как проектировать fd lifecycle policy в большом сервисе?</p>\n","answer":"<p><strong>Ответ:</strong> Один owner закрывает fd, borrow не переживает owner, transfer явный; регистрация events входит в lifecycle.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L4","line":844},{"id":"content/06_tools_build_debug/05_runtime.md:737bed350b610abb:1","question":"<p>(L4, D) Как расследовать деградацию сервиса из-за fd exhaustion?</p>\n","answer":"<p><strong>Ответ:</strong> Собрать count/limits/errors и типы fd, ограничить admission, локализовать leaking path; повышение лимита не устраняет утечку.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L4","line":850},{"id":"content/06_tools_build_debug/05_runtime.md:15382f199251c13b:1","question":"<p>(L4, S) Как формализовать ownership fd в C/C++ коде?</p>\n","answer":"<p><strong>Ответ:</strong> Move-only RAII owner и явные borrowed views; запрет неоговорённого close у потребителя borrowed fd.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L4","line":856},{"id":"content/06_tools_build_debug/05_runtime.md:4ab900376cb1c475:1","question":"<p>(L4, S) Как строить безопасные RAII-обертки над системными ресурсами?</p>\n","answer":"<p><strong>Ответ:</strong> Хранить invalid sentinel -1, запрещать copy, поддерживать move и однократное закрытие; destructor не бросает исключения.</p>\n<p><strong>Пример:</strong> Минимальный Linux RAII owner; ownership передаётся явно.</p>\n<pre><code class=\"language-cpp\">#include &lt;unistd.h&gt;\n#include &lt;utility&gt;\n\nclass unique_fd {\n    int fd_ = -1;\npublic:\n    explicit unique_fd(int fd = -1) noexcept : fd_(fd) {}\n    ~unique_fd() { if (fd_ != -1) ::close(fd_); }\n    unique_fd(const unique_fd&amp;) = delete;\n    unique_fd&amp; operator=(const unique_fd&amp;) = delete;\n    unique_fd(unique_fd&amp;&amp; other) noexcept\n        : fd_(std::exchange(other.fd_, -1)) {}\n    unique_fd&amp; operator=(unique_fd&amp;&amp; other) noexcept {\n        if (this != &amp;other) {\n            if (fd_ != -1) ::close(fd_);\n            fd_ = std::exchange(other.fd_, -1);\n        }\n        return *this;\n    }\n    int get() const noexcept { return fd_; } // Borrowed descriptor.\n    int release() noexcept { return std::exchange(fd_, -1); }\n};\n</code></pre>\n<p>Destructor не сообщает errors закрытия. Если write durability/error важны, нужен явный checked finalization path; для файлов durability отдельно требует appropriate sync policy.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L4","line":862},{"id":"content/06_tools_build_debug/05_runtime.md:cb0479d09ba0756a:1","question":"<p>(L4, D) Как находить subtle bugs, связанные с переиспользованием fd ядром?</p>\n","answer":"<p><strong>Ответ:</strong> Использовать generation IDs и owner checks; старое событие с числом fd может относиться уже к новому ресурсу.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">open(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/fcntl.2.html\">fcntl(2)</a>; <a href=\"https://man7.org/linux/man-pages/man2/close.2.html\">close(2)</a></p>\n","group":"L4","line":897},{"id":"content/06_tools_build_debug/05_runtime.md:2364f5d0ad78450f:1","question":"<p>(L1, T) Что такое signal в Linux?</p>\n","answer":"<p><strong>Ответ:</strong> Механизм уведомления процесса/потока о событии с disposition, mask и правилами доставки.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L1","line":908},{"id":"content/06_tools_build_debug/05_runtime.md:1debfb70a484ce8f:1","question":"<p>(L1, T) Какие сигналы чаще всего встречаются в практике C/C++?</p>\n","answer":"<p><strong>Ответ:</strong> SIGINT, SIGTERM, SIGCHLD, SIGPIPE, SIGSEGV, SIGABRT; смысл и действие зависят от сигнала и disposition.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L1","line":914},{"id":"content/06_tools_build_debug/05_runtime.md:c6c780a14565a00a:1","question":"<p>(L1, T) Чем <code>SIGINT</code>, <code>SIGTERM</code>, <code>SIGKILL</code> отличаются?</p>\n","answer":"<p><strong>Ответ:</strong> SIGINT — обычно interrupt терминала; SIGTERM — запрос завершения; SIGKILL принудительно завершает без handler/cleanup.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L1","line":920},{"id":"content/06_tools_build_debug/05_runtime.md:f80efaf1a095ae56:1","question":"<p>(L1, T) Какие сигналы обычно означают crash?</p>\n","answer":"<p><strong>Ответ:</strong> SIGSEGV, SIGBUS, SIGILL, SIGFPE и SIGABRT часто приводят к аварийному завершению; они не всегда доказывают первопричину.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L1","line":926},{"id":"content/06_tools_build_debug/05_runtime.md:9e243a31c9fa0bb5:1","question":"<p>(L1, P) Как установить signal handler?</p>\n","answer":"<p><strong>Ответ:</strong> Настроить <code>struct sigaction</code>, mask и flags, вызвать <code>sigaction</code>; handler должен соблюдать async-signal-safety.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L1","line":932},{"id":"content/06_tools_build_debug/05_runtime.md:075e63698a8a9975:1","question":"<p>(L1, D) Почему нельзя просто “делать всё что угодно” внутри signal handler?</p>\n","answer":"<p><strong>Ответ:</strong> Он может прервать code с удержанными internal locks; небезопасный повторный вызов runtime приводит к deadlock/corruption.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L1","line":938},{"id":"content/06_tools_build_debug/05_runtime.md:fc002cacc926db4e:1","question":"<p>(L1, T) Что значит asynchronous signal delivery?</p>\n","answer":"<p><strong>Ответ:</strong> Signal может быть обработан вне обычного control flow; thread-directed и синхронные fault signals имеют дополнительные правила.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L1","line":944},{"id":"content/06_tools_build_debug/05_runtime.md:ce6093f8e912b6dd:1","question":"<p>(L1, D) Почему <code>SIGKILL</code> нельзя перехватить?</p>\n","answer":"<p><strong>Ответ:</strong> Ядро не разрешает менять disposition SIGKILL и SIGSTOP; процесс не может заблокировать их mask.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L1","line":950},{"id":"content/06_tools_build_debug/05_runtime.md:02b013e79a3a1256:1","question":"<p>(L1, T) Что обычно делает <code>SIGCHLD</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Уведомляет parent об изменении состояния child; требуется собрать statuses через wait, обычно в цикле.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L1","line":956},{"id":"content/06_tools_build_debug/05_runtime.md:50f514be3177f58f:1","question":"<p>(L1, P) Как корректно завершать программу по <code>SIGTERM</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Передать событие normal control flow, остановить admission, разбудить workers и завершить в ограниченный deadline.</p>\n<p><strong>Типичная ошибка:</strong> Вызывать logger, delete объектов и join потоков непосредственно из asynchronous handler. Достаточно передать событие нормальному control flow.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L1","line":962},{"id":"content/06_tools_build_debug/05_runtime.md:b847d2b70ccab784:1","question":"<p>(L2, T) Что такое async-signal-safe functions?</p>\n","answer":"<p><strong>Ответ:</strong> Функции из POSIX signal-safety contract, например write и _exit; это отдельное свойство от thread safety.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L2","line":973},{"id":"content/06_tools_build_debug/05_runtime.md:f5c6c0029c32ec2c:1","question":"<p>(L2, D) Почему <code>printf</code>, <code>malloc</code>, mutex'ы и большинство C++ API опасны в signal handler?</p>\n","answer":"<p><strong>Ответ:</strong> Они используют locks и состояние, которое могло быть прервано handler; reentrancy не гарантируется.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L2","line":979},{"id":"content/06_tools_build_debug/05_runtime.md:f19fd54c9b5aeae5:1","question":"<p>(L2, D) Как безопасно передавать факт получения сигнала в main loop?</p>\n","answer":"<p><strong>Ответ:</strong> Использовать self-pipe или централизованный sigwait/signalfd; простой <code>volatile sig_atomic_t</code> годится для ограниченного signal/main сценария.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L2","line":985},{"id":"content/06_tools_build_debug/05_runtime.md:7c685686dfa0b748:1","question":"<p>(L2, T) Что такое signal mask?</p>\n","answer":"<p><strong>Ответ:</strong> Набор временно blocked signals для потока; dispositions обычно общие для процесса.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L2","line":991},{"id":"content/06_tools_build_debug/05_runtime.md:e7a4c70ffd8ac9dc:1","question":"<p>(L2, P) Как блокировать/разблокировать сигналы в потоке?</p>\n","answer":"<p><strong>Ответ:</strong> В multithreaded коде вызвать <code>pthread_sigmask</code>, проверив return code; задавать mask до создания workers.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L2","line":997},{"id":"content/06_tools_build_debug/05_runtime.md:bcea6d552126ee0a:1","question":"<p>(L2, T) Как сигналы взаимодействуют с многопоточностью?</p>\n","answer":"<p><strong>Ответ:</strong> Mask индивидуальна, dispositions общие; process-directed signal доставляется одному из подходящих unblocked threads.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L2","line":1003},{"id":"content/06_tools_build_debug/05_runtime.md:724f39e675be6d95:1","question":"<p>(L2, D) Почему сигнал пришел “не в тот поток”?</p>\n","answer":"<p><strong>Ответ:</strong> Для process-directed signal ядро выбирает допустимый поток; централизовать приём через заранее настроенные masks.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L2","line":1009},{"id":"content/06_tools_build_debug/05_runtime.md:82d9d14b93963111:1","question":"<p>(L2, T) Что такое <code>sigaction</code> и почему он лучше старого <code>signal()</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Даёт явные flags, handler mode и mask; семантика старого signal исторически различалась между системами.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L2","line":1015},{"id":"content/06_tools_build_debug/05_runtime.md:2aa624df0878e08c:1","question":"<p>(L2, D) Как сигналы влияют на системные вызовы и I/O?</p>\n","answer":"<p><strong>Ответ:</strong> Могут прервать blocking calls или вызвать restart; обработка EINTR и deadlines нужна независимо от handler.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L2","line":1021},{"id":"content/06_tools_build_debug/05_runtime.md:624113e6dddb6473:1","question":"<p>(L2, P) Как построить graceful shutdown через signals?</p>\n","answer":"<p><strong>Ответ:</strong> Получить сигнал в control thread/loop, выставить stop state, остановить новые запросы, drain/timeout и join workers.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L2","line":1027},{"id":"content/06_tools_build_debug/05_runtime.md:71933f55fb0d5005:1","question":"<p>(L3, D) Как расследовать нестабильные баги, вызванные сигналами?</p>\n","answer":"<p><strong>Ответ:</strong> Собрать masks/dispositions, siginfo и stacks, проверить unsafe handler operations и неверные ожидания signal queueing.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L3","line":1036},{"id":"content/06_tools_build_debug/05_runtime.md:8cb6c010ed161606:1","question":"<p>(L3, T) Что такое self-pipe trick и зачем он нужен?</p>\n","answer":"<p><strong>Ответ:</strong> Handler делает неблокирующий write в pipe, loop читает pipe и выполняет работу обычным кодом; обработать заполнение pipe.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L3","line":1042},{"id":"content/06_tools_build_debug/05_runtime.md:2615d720f360433d:1","question":"<p>(L3, T) Как <code>signalfd</code> упрощает event-driven обработку сигналов?</p>\n","answer":"<p><strong>Ответ:</strong> Заблокированные signals читаются как records из fd; его можно включить в epoll без асинхронного handler для этих signals.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L3","line":1048},{"id":"content/06_tools_build_debug/05_runtime.md:5c862ef13a0bd6d6:1","question":"<p>(L3, D) Почему обработка сигналов и потоки вместе часто приводят к сложным ошибкам?</p>\n","answer":"<p><strong>Ответ:</strong> Mask, выбранный thread и прерванные locks образуют сложные interleavings; общий signal policy уменьшает пространство ошибок.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L3","line":1054},{"id":"content/06_tools_build_debug/05_runtime.md:1261cee99e06b786:1","question":"<p>(L3, D) Как отличить crash по <code>SIGSEGV</code> из-за кода от crash из-за внешнего воздействия?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить siginfo si_code/si_addr и core stack: fault и отправленный kill/tgkill signal имеют разные признаки.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L3","line":1060},{"id":"content/06_tools_build_debug/05_runtime.md:37104a8897bc30b7:1","question":"<p>(L3, S) Когда лучше обрабатывать signals централизованно в одном потоке?</p>\n","answer":"<p><strong>Ответ:</strong> Для control signals daemon: заранее блокировать их во всех workers и принимать в sigwait/control thread.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L3","line":1066},{"id":"content/06_tools_build_debug/05_runtime.md:2d852a3f714e23df:1","question":"<p>(L3, D) Почему fork/exec + signals требуют особой аккуратности?</p>\n","answer":"<p><strong>Ответ:</strong> Mask наследуется; exec сбрасывает caught dispositions, но сохраняет ignored и mask, что может неожиданно блокировать signals новой программы.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L3","line":1072},{"id":"content/06_tools_build_debug/05_runtime.md:bb97b234b07bd534:1","question":"<p>(L3, P) Как интегрировать signals в epoll/event-loop архитектуру?</p>\n","answer":"<p><strong>Ответ:</strong> Создать signalfd для заранее blocked набора, зарегистрировать EPOLLIN и читать records в обычном handler loop.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L3","line":1078},{"id":"content/06_tools_build_debug/05_runtime.md:b39042f0e606e108:1","question":"<p>(L3, D) Как диагностировать lost/repeated signal handling bugs?</p>\n","answer":"<p><strong>Ответ:</strong> Обычные signals могут объединяться; проверить masks, pending state и counting assumptions. Для счётных событий нужен другой механизм.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L3","line":1084},{"id":"content/06_tools_build_debug/05_runtime.md:8857baf4b00e5a40:1","question":"<p>(L3, S) Как проектировать signal-safe shutdown path?</p>\n","answer":"<p><strong>Ответ:</strong> Handler только сообщает событие; cleanup, locks и joins выполняются normal flow с идемпотентными transitions и deadline.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L3","line":1090},{"id":"content/06_tools_build_debug/05_runtime.md:eec6663671d6ea99:1","question":"<p>(L4, S) Как проектировать signal policy для production daemon/service?</p>\n","answer":"<p><strong>Ответ:</strong> Документировать control/fault signals, masks, shutdown/reload semantics и supervision escalation; проверять интеграционными тестами.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L4","line":1099},{"id":"content/06_tools_build_debug/05_runtime.md:fef5dedf243a8fbd:1","question":"<p>(L4, D) Как расследовать аварийное завершение, где signals — только симптом?</p>\n","answer":"<p><strong>Ответ:</strong> Сопоставить fault address, crashing instruction, memory ownership и предшествующие ошибки; сигнал описывает механизм остановки.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L4","line":1105},{"id":"content/06_tools_build_debug/05_runtime.md:07e8ad62f903935c:1","question":"<p>(L4, S) Как обучать команду безопасной работе с signal handlers?</p>\n","answer":"<p><strong>Ответ:</strong> Использовать минимальный approved handler pattern и review signal-safe calls; проверять сценарии прихода сигнала в любой момент.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L4","line":1111},{"id":"content/06_tools_build_debug/05_runtime.md:aededc40c6bc7cdb:1","question":"<p>(L4, D) Как формализовать требования к shutdown/reload semantics через сигналы?</p>\n","answer":"<p><strong>Ответ:</strong> Определить admission/drain, timeout, повторный сигнал и атомарное применение reload; публиковать видимый статус результата.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L4","line":1117},{"id":"content/06_tools_build_debug/05_runtime.md:d12e82263bd233d4:1","question":"<p>(L4, S) Как сочетать signals, supervision и observability в Linux runtime?</p>\n","answer":"<p><strong>Ответ:</strong> Supervisor задаёт termination deadline и restart policy; сервис логирует lifecycle transitions и exit status вне unsafe handler.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/signal.7.html\">signal(7)</a>; <a href=\"https://man7.org/linux/man-pages/man7/signal-safety.7.html\">signal-safety(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/signalfd.2.html\">signalfd(2)</a></p>\n","group":"L4","line":1123},{"id":"content/06_tools_build_debug/05_runtime.md:767f699b358de522:1","question":"<p>(L1, T) Что такое multiplexed I/O?</p>\n","answer":"<p><strong>Ответ:</strong> Ожидание готовности нескольких I/O sources одним потоком вместо отдельного blocking wait на каждый.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L1","line":1134},{"id":"content/06_tools_build_debug/05_runtime.md:e0ead487cf515c10:1","question":"<p>(L1, T) Зачем нужен <code>select()</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Позволяет ждать read/write/exception readiness набора fd с timeout.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L1","line":1140},{"id":"content/06_tools_build_debug/05_runtime.md:38e56ffb740c6d9d:1","question":"<p>(L1, T) Какие ограничения у <code>select()</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Fd ограничены FD_SETSIZE у обычного API, sets изменяются вызовом, сканирование растёт с диапазоном fd.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L1","line":1146},{"id":"content/06_tools_build_debug/05_runtime.md:510d8ddb265e5376:1","question":"<p>(L1, T) Что делает <code>epoll</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Поддерживает persistent interest list и возвращает ready events для зарегистрированных descriptors.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L1","line":1152},{"id":"content/06_tools_build_debug/05_runtime.md:ea6e6644eea915f6:1","question":"<p>(L1, T) Почему <code>epoll</code> часто предпочтительнее <code>select()</code> на Linux?</p>\n","answer":"<p><strong>Ответ:</strong> Удобнее для больших sparse sets соединений и не ограничен fd_set; стоимость всё равно зависит от событий и операций.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L1","line":1158},{"id":"content/06_tools_build_debug/05_runtime.md:c0630fa5b30aa301:1","question":"<p>(L1, T) Что значит readiness-based I/O?</p>\n","answer":"<p><strong>Ответ:</strong> Уведомление, что операция может продвинуться без blocking; фактический syscall всё равно может вернуть EAGAIN.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L1","line":1164},{"id":"content/06_tools_build_debug/05_runtime.md:776b2b8911dcde71:1","question":"<p>(L1, P) Как на базовом уровне ждать готовности fd к чтению?</p>\n","answer":"<p><strong>Ответ:</strong> Для nonblocking fd использовать poll/epoll_wait, затем read/recv и проверить result; readiness не заменяет обработку ошибок.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L1","line":1170},{"id":"content/06_tools_build_debug/05_runtime.md:f3263c7db3142d4b:1","question":"<p>(L1, D) Почему blocking I/O плохо масштабируется на множество соединений?</p>\n","answer":"<p><strong>Ответ:</strong> Thread-per-connection расходует stacks и scheduler resources; для ограниченной concurrency blocking модель может быть достаточной.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L1","line":1176},{"id":"content/06_tools_build_debug/05_runtime.md:fb8481ed0fc110fa:1","question":"<p>(L1, T) Чем polling отличается от event-driven подхода?</p>\n","answer":"<p><strong>Ответ:</strong> Busy polling активно проверяет состояние, event-driven ждёт уведомления; системный вызов poll сам может эффективно спать.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L1","line":1182},{"id":"content/06_tools_build_debug/05_runtime.md:11a9e52cd060346c:1","question":"<p>(L1, D) Почему event loop сложнее, но масштабируемее?</p>\n","answer":"<p><strong>Ответ:</strong> Он обслуживает много ожидающих fd малым числом threads, но требует state machines, bounded handlers и lifecycle discipline.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L1","line":1188},{"id":"content/06_tools_build_debug/05_runtime.md:7677605a9451118a:1","question":"<p>(L2, T) Что такое level-triggered и edge-triggered режимы в epoll?</p>\n","answer":"<p><strong>Ответ:</strong> LT сообщает пока условие readiness сохраняется; ET — о переходах, поэтому fd должен быть nonblocking и обычно drain до EAGAIN.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L2","line":1197},{"id":"content/06_tools_build_debug/05_runtime.md:0ad0c571223be47f:1","question":"<p>(L2, D) Почему edge-triggered режим часто вызывает ошибки у новичков?</p>\n","answer":"<p><strong>Ответ:</strong> Если не дочитать доступные данные и ждать нового edge, connection может зависнуть без нового уведомления.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L2","line":1203},{"id":"content/06_tools_build_debug/05_runtime.md:310abc5dd168e777:1","question":"<p>(L2, P) Как правильно читать из non-blocking socket в event loop?</p>\n","answer":"<p><strong>Ответ:</strong> Читать в цикле, учитывать bytes/EOF/EINTR, останавливаться на EAGAIN; fairness budget должен сохранять возможность продолжения.</p>\n<p><strong>Пример:</strong> Ветка чтения nonblocking socket, без полного protocol parser:</p>\n<pre><code class=\"language-c\">for (;;) {\n    ssize_t n = recv(fd, buf, sizeof(buf), 0);\n    if (n &gt; 0) {\n        /* Добавить n bytes в bounded input/parser state. */\n        continue;\n    }\n    if (n == 0) { /* Peer закрыл write side. */ break; }\n    if (errno == EINTR) continue;\n    if (errno == EAGAIN || errno == EWOULDBLOCK) break;\n    /* Сохранить errno, обработать ошибку connection. */\n    break;\n}\n</code></pre>\n<p>В ET при раннем выходе ради fairness нужно запланировать продолжение, не полагаясь на новый edge. Обработка EOF/error меняет lifecycle connection, а не только выходит из цикла.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L2","line":1209},{"id":"content/06_tools_build_debug/05_runtime.md:a1265fa06bdac046:1","question":"<p>(L2, D) Почему нельзя предполагать, что один event = все данные прочитаны?</p>\n","answer":"<p><strong>Ответ:</strong> Событие относится к readiness, не к границе сообщения; объём и framing определяет protocol/parser.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L2","line":1234},{"id":"content/06_tools_build_debug/05_runtime.md:4f07fb4d322ccefd:1","question":"<p>(L2, D) Как <code>EAGAIN</code> связан с epoll/non-blocking I/O?</p>\n","answer":"<p><strong>Ответ:</strong> Показывает отсутствие дальнейшего немедленного progress; возвращают управление loop и ждут соответствующего readiness.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L2","line":1240},{"id":"content/06_tools_build_debug/05_runtime.md:15ec6c7193ff9c3e:1","question":"<p>(L2, P) Как добавить, изменить и удалить fd из epoll interest list?</p>\n","answer":"<p><strong>Ответ:</strong> Вызвать <code>epoll_ctl</code> с EPOLL_CTL_ADD/MOD/DEL; проверить return value и привязать стабильный owner/generation token.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L2","line":1246},{"id":"content/06_tools_build_debug/05_runtime.md:b518acb47695b091:1","question":"<p>(L2, D) Почему event loop может “крутиться” и жечь CPU?</p>\n","answer":"<p><strong>Ответ:</strong> Постоянный EPOLLOUT, необработанный HUP/EOF, нулевые timeouts или повторные EAGAIN без ожидания.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L2","line":1252},{"id":"content/06_tools_build_debug/05_runtime.md:0b801f9d2a931ae9:1","question":"<p>(L2, T) Что такое thundering herd problem?</p>\n","answer":"<p><strong>Ответ:</strong> Много waiters пробуждаются на одну доступную работу; уменьшают конкуренцию ownership/partitioning и поддерживаемыми wakeup flags.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L2","line":1258},{"id":"content/06_tools_build_debug/05_runtime.md:ad0baa8ae93f1cf8:1","question":"<p>(L2, D) Как ошибки lifecycle fd ломают epoll-based код?</p>\n","answer":"<p><strong>Ответ:</strong> Закрытие/reuse и stale events могут обратиться к другому connection; удаление регистрации не аннулирует уже выданный event batch.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L2","line":1264},{"id":"content/06_tools_build_debug/05_runtime.md:e4b257acc3b95d35:1","question":"<p>(L2, S) Когда <code>select/poll/epoll</code> достаточно, а когда нужна более высокая абстракция?</p>\n","answer":"<p><strong>Ответ:</strong> Низкий API достаточен небольшой системе; библиотека полезна для переносимости, timers, cancellation и проверенных lifecycle contracts.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L2","line":1270},{"id":"content/06_tools_build_debug/05_runtime.md:fbda80493138bc75:1","question":"<p>(L3, D) Как расследовать lost wakeup / missed event в epoll-системе?</p>\n","answer":"<p><strong>Ответ:</strong> Записать ADD/MOD/DEL, mask, I/O results и transitions; проверить ET drain, ONESHOT rearm и races публикации работы.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L3","line":1279},{"id":"content/06_tools_build_debug/05_runtime.md:3d88dd3afd9fc991:1","question":"<p>(L3, D) Почему readiness не равна progress в I/O?</p>\n","answer":"<p><strong>Ответ:</strong> Другой consumer может забрать данные или условие изменится; readiness может вести к EOF/error, а не payload.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L3","line":1285},{"id":"content/06_tools_build_debug/05_runtime.md:089622fded0a34ef:1","question":"<p>(L3, T) Как epoll ведет себя при закрытии fd в другом потоке?</p>\n","answer":"<p><strong>Ответ:</strong> Ожидающий epoll_wait не обязан проснуться; registration связан с fd и open file description, а dup references усложняют удаление.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L3","line":1291},{"id":"content/06_tools_build_debug/05_runtime.md:50501ea9426dc875:1","question":"<p>(L3, D) Почему fd reuse может приводить к трудноуловимым epoll bug'ам?</p>\n","answer":"<p><strong>Ответ:</strong> Число fd быстро переиспользуется, а старый event/state ещё существует; нужны generation checks и согласованный owner.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L3","line":1297},{"id":"content/06_tools_build_debug/05_runtime.md:94db54d64e156653:1","question":"<p>(L3, D) Как проектировать backpressure в event-driven сервере?</p>\n","answer":"<p><strong>Ответ:</strong> Ограничить очереди/bytes per connection, приостанавливать ingress, возобновлять по low watermark и задавать overload policy.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L3","line":1303},{"id":"content/06_tools_build_debug/05_runtime.md:1557c773c78244be:1","question":"<p>(L3, T) Что такое reactor pattern и как он связан с epoll?</p>\n","answer":"<p><strong>Ответ:</strong> Reactor ждёт readiness и вызывает handlers, которые делают nonblocking I/O; epoll реализует механизм ожидания на Linux.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L3","line":1309},{"id":"content/06_tools_build_debug/05_runtime.md:025e8e5fffd4210a:1","question":"<p>(L3, D) Как отличить bottleneck event-loop'а от bottleneck бизнес-логики?</p>\n","answer":"<p><strong>Ответ:</strong> Измерять loop lag, handler duration, queue depth и worker utilization; profile привязать к запросному latency.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L3","line":1315},{"id":"content/06_tools_build_debug/05_runtime.md:db2d762c790eafb6:1","question":"<p>(L3, P) Как интегрировать timerfd/eventfd/signalfd в epoll loop?</p>\n","answer":"<p><strong>Ответ:</strong> Создать соответствующие nonblocking CLOEXEC fd, добавить EPOLLIN и полностью обработать формат чтения/счётчики каждого API.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L3","line":1321},{"id":"content/06_tools_build_debug/05_runtime.md:7c4caa4470f19192:1","question":"<p>(L3, D) Как расследовать latency spikes в epoll-based сервере?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить long callbacks, unfair batching, worker queues, CPU throttling, timers и allocation stalls.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L3","line":1327},{"id":"content/06_tools_build_debug/05_runtime.md:de85542a468a09fa:1","question":"<p>(L3, S) Когда стоит делить I/O loop и worker pool?</p>\n","answer":"<p><strong>Ответ:</strong> Когда CPU-heavy или blocking business work нарушает I/O deadlines; нужен bounded pool и безопасная передача ownership/result.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L3","line":1333},{"id":"content/06_tools_build_debug/05_runtime.md:dd60d024f2d0c79f:1","question":"<p>(L4, S) Как проектировать high-load event-driven runtime на Linux?</p>\n","answer":"<p><strong>Ответ:</strong> Shard connections по owners, nonblocking I/O, bounded queues, timers/cancellation и явные shutdown states; измерять SLO под overload.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L4","line":1342},{"id":"content/06_tools_build_debug/05_runtime.md:9e00dbda2ffcd8ef:1","question":"<p>(L4, S) Как выбирать между thread-per-connection, pool и epoll/reactor?</p>\n","answer":"<p><strong>Ответ:</strong> По concurrency, blocking requirements, CPU work и team complexity budget; benchmark должен включать overload и tail latency.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L4","line":1348},{"id":"content/06_tools_build_debug/05_runtime.md:6872c9dc62c3f6ee:1","question":"<p>(L4, D) Как расследовать масштабируемость event-loop архитектуры на production?</p>\n","answer":"<p><strong>Ответ:</strong> Снять scaling curve, loop lag, CPU/queue profiles и cgroup limits; отделить saturation одного shard от общей нагрузки.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L4","line":1354},{"id":"content/06_tools_build_debug/05_runtime.md:e4659b64c0ec8a06:1","question":"<p>(L4, S) Как обеспечить корректность fd/event lifecycle при сложной архитектуре?</p>\n","answer":"<p><strong>Ответ:</strong> Один owner transitions/close, generation handles, отмена pending tasks и quiescence перед уничтожением context.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">epoll(7)</a>; <a href=\"https://man7.org/linux/man-pages/man2/epoll_ctl.2.html\">epoll_ctl(2)</a></p>\n","group":"L4","line":1360},{"id":"content/06_tools_build_debug/05_runtime.md:0109c1d8e1ce2102:1","question":"<p>(L4, S) Как строить performance/debugging playbook для epoll-based сервисов?</p>\n","answer":"<p><strong>Ответ:</strong> Зафиксировать команды fd/limits, scheduler traces, loop metrics и capture state machines; для каждого symptom дать проверяемые гипотезы.</p>\n<pre><code> **Источник:** [epoll(7)](https://man7.org/linux/man-pages/man7/epoll.7.html); [epoll_ctl(2)](https://man7.org/linux/man-pages/man2/epoll_ctl.2.html)\n</code></pre>\n<hr />\n","group":"L4","line":1366},{"id":"content/06_tools_build_debug/05_runtime.md:d0d451f5972c6ad5:1","question":"<p>(L1, T) Что такое dynamic loading?</p>\n","answer":"<p><strong>Ответ:</strong> Загрузка executable module во время работы процесса вместо обязательного включения в startup dependencies.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L1","line":1381},{"id":"content/06_tools_build_debug/05_runtime.md:2f71e2f208ccdd3c:1","question":"<p>(L1, T) Что делает <code>dlopen()</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Загружает shared object и dependencies, выполняет необходимые relocations/initializers и возвращает handle либо NULL.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L1","line":1387},{"id":"content/06_tools_build_debug/05_runtime.md:282c839bb71f765b:1","question":"<p>(L1, T) Что делает <code>dlsym()</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Ищет symbol по имени в области handle; ошибку определяют через dlerror, поскольку NULL может быть значением symbol.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L1","line":1393},{"id":"content/06_tools_build_debug/05_runtime.md:bbc1ebd7713f0c07:1","question":"<p>(L1, T) Что такое plugin на базовом уровне?</p>\n","answer":"<p><strong>Ответ:</strong> Загружаемый модуль с согласованным extension API и lifecycle, предоставляющий host дополнительное поведение.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L1","line":1399},{"id":"content/06_tools_build_debug/05_runtime.md:a4896f103f0a4c02:1","question":"<p>(L1, P) Как загрузить <code>.so</code> во время выполнения?</p>\n","answer":"<p><strong>Ответ:</strong> <code>dlopen(path, RTLD_NOW | RTLD_LOCAL)</code>, проверить handle/dlerror, найти entry point и проверить ABI до вызова.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L1","line":1405},{"id":"content/06_tools_build_debug/05_runtime.md:27efd29629c3c2d8:1","question":"<p>(L2, T) Что означают <code>RTLD_LAZY</code> и <code>RTLD_NOW</code>?</p>\n","answer":"<p><strong>Ответ:</strong> LAZY откладывает поддерживаемые function bindings до использования; NOW разрешает необходимые undefined symbols при загрузке.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L2","line":1414},{"id":"content/06_tools_build_debug/05_runtime.md:adb2d791e3da2f48:1","question":"<p>(L2, T) Что такое <code>RTLD_LOCAL</code> и <code>RTLD_GLOBAL</code>?</p>\n","answer":"<p><strong>Ответ:</strong> LOCAL ограничивает доступность symbols для последующих загрузок; GLOBAL делает их доступными в global lookup scope.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L2","line":1420},{"id":"content/06_tools_build_debug/05_runtime.md:75f9abf666bc9c5b:1","question":"<p>(L2, D) Почему <code>dlopen()</code> может не найти библиотеку?</p>\n","answer":"<p><strong>Ответ:</strong> Неверный path/search policy, отсутствующая dependency, неподходящая architecture или permissions; читать dlerror.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L2","line":1426},{"id":"content/06_tools_build_debug/05_runtime.md:1520863ff7afc6ac:1","question":"<p>(L2, D) Почему <code>dlsym()</code> возвращает <code>NULL</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Возможны отсутствие symbol и scope/version mismatch; только dlerror отличает lookup error от допустимого NULL value.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L2","line":1432},{"id":"content/06_tools_build_debug/05_runtime.md:c8fe19a9a09a9a98:1","question":"<p>(L2, P) Как корректно объявлять API плагина для загрузки через <code>dlsym()</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Экспортировать C-compatible entry point с фиксированной signature и versioned table; host обязан использовать точно совпадающий function type.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L2","line":1438},{"id":"content/06_tools_build_debug/05_runtime.md:666ec4c26dd90bc3:1","question":"<p>(L2, T) Почему <code>extern &quot;C&quot;</code> часто нужен для plugin entry points?</p>\n","answer":"<p><strong>Ответ:</strong> Отключает C++ name mangling для entry symbol; совместимость layout, ownership и calling convention этим не гарантируется.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L2","line":1444},{"id":"content/06_tools_build_debug/05_runtime.md:8639335f791ae2b8:1","question":"<p>(L2, D) Как проверить <code>dlerror()</code> и почему это важно?</p>\n","answer":"<p><strong>Ответ:</strong> Сначала очистить старую ошибку <code>dlerror()</code>, вызвать dlsym, затем проверить новый <code>dlerror()</code>; сообщения копировать при необходимости.</p>\n<p><strong>Пример:</strong> Фрагмент для POSIX dlsym:</p>\n<pre><code class=\"language-c\">typedef int (*plugin_init_fn)(void);\ndlerror();\nvoid *symbol = dlsym(handle, &quot;plugin_init_v1&quot;);\nconst char *error = dlerror();\nif (error != NULL) {\n    /* Lookup failure: скопировать/сообщить error обычным кодом. */\n} else if (symbol == NULL) {\n    /* Для function entry point это непригодный адрес. */\n} else {\n    plugin_init_fn init = (plugin_init_fn)symbol;\n    /* Вызывать только при совпадении documented ABI/signature. */\n    int result = init();\n    (void)result;\n}\n</code></pre>\n<p>Преобразование object pointer в function pointer здесь опирается на POSIX contract dlsym, не на универсальную переносимость ISO C.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L2","line":1450},{"id":"content/06_tools_build_debug/05_runtime.md:06574772ddc6a203:1","question":"<p>(L2, T) Что происходит с зависимостями загружаемой <code>.so</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Loader ищет DT_NEEDED dependencies и выполняет relocations; наличие main .so не гарантирует доступность всех зависимостей.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L2","line":1477},{"id":"content/06_tools_build_debug/05_runtime.md:cf4a1cc79535b80b:1","question":"<p>(L2, D) Почему plugin может загрузиться, но упасть при первом вызове функции?</p>\n","answer":"<p><strong>Ответ:</strong> Signature/ABI mismatch, неинициализированный context, отсутствующая lazy dependency или нарушение ownership; проверить loader error и stack.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L2","line":1483},{"id":"content/06_tools_build_debug/05_runtime.md:32d539f831d5d5da:1","question":"<p>(L2, P) Как выгрузить библиотеку через <code>dlclose()</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Сначала остановить работу plugin и убрать все references/callbacks, затем <code>dlclose(handle)</code>; физическая выгрузка не гарантирована.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L2","line":1489},{"id":"content/06_tools_build_debug/05_runtime.md:16c8c89abdfd58f3:1","question":"<p>(L3, T) Как symbol visibility влияет на dynamic loading?</p>\n","answer":"<p><strong>Ответ:</strong> Hidden symbols не становятся обычным public dynamic API; entry points нужно экспортировать явно.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L3","line":1498},{"id":"content/06_tools_build_debug/05_runtime.md:ca46ce3bfb5d48f4:1","question":"<p>(L3, D) Почему возникают конфликты символов между host и plugin?</p>\n","answer":"<p><strong>Ответ:</strong> Global lookup/interposition связывает одинаковые имена с неожиданной реализацией; ограничивать exports и область видимости.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L3","line":1504},{"id":"content/06_tools_build_debug/05_runtime.md:42bcc3e50812a282:1","question":"<p>(L3, D) Как ABI mismatch проявляется при dynamic loading?</p>\n","answer":"<p><strong>Ответ:</strong> Неверные аргументы/layout, vtable corruption, allocator mismatch и crashes; link/load success не доказывает ABI compatibility.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L3","line":1510},{"id":"content/06_tools_build_debug/05_runtime.md:abb545ae46b99699:1","question":"<p>(L3, T) Почему C++ классы через границу plugin ABI — рискованная идея?</p>\n","answer":"<p><strong>Ответ:</strong> Layout, mangling, exceptions, STL и runtime ABI зависят от toolchain; crossing boundary требует жёсткой compatibility policy.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L3","line":1516},{"id":"content/06_tools_build_debug/05_runtime.md:39bf5f9b529070cc:1","question":"<p>(L3, S) Как проектировать stable C-compatible plugin ABI?</p>\n","answer":"<p><strong>Ответ:</strong> Version/size fields, fixed-width types, opaque handles, явные error codes и destroy functions на стороне allocator owner.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L3","line":1522},{"id":"content/06_tools_build_debug/05_runtime.md:497e300e53bf336e:1","question":"<p>(L3, D) Почему <code>dlclose()</code> может быть опасен в многопоточном приложении?</p>\n","answer":"<p><strong>Ответ:</strong> Другой поток может исполнять plugin code или держать callbacks/TLS/destructors; нужна quiescence всех пользователей.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L3","line":1528},{"id":"content/06_tools_build_debug/05_runtime.md:0dd319c64689ac3a:1","question":"<p>(L3, D) Как расследовать crash в plugin после reload/unload?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить stale function pointers, живые objects/tasks, callbacks, TLS и reload generations; сопоставить crash address с mappings.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L3","line":1534},{"id":"content/06_tools_build_debug/05_runtime.md:828275fc3780eb38:1","question":"<p>(L3, P) Как анализировать экспортируемые символы plugin <code>.so</code>?</p>\n","answer":"<p><strong>Ответ:</strong> <code>nm -D --defined-only plugin.so</code> и <code>readelf --dyn-syms plugin.so</code>; обычная symbol table не равна dynamic exports.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L3","line":1540},{"id":"content/06_tools_build_debug/05_runtime.md:6d73418b21c6faa3:1","question":"<p>(L3, D) Как versioning plugin API помогает избежать runtime crash?</p>\n","answer":"<p><strong>Ответ:</strong> Host проверяет version/capabilities/size до вызовов и отклоняет несовместимый модуль, а не угадывает layout.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L3","line":1546},{"id":"content/06_tools_build_debug/05_runtime.md:e0a76d69e672cfff:1","question":"<p>(L3, S) Когда dynamic loading оправдан архитектурно, а когда это overengineering?</p>\n","answer":"<p><strong>Ответ:</strong> Когда нужны независимые extensions/deployment; если все модули выпускаются вместе, обычная linking может быть проще.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L3","line":1552},{"id":"content/06_tools_build_debug/05_runtime.md:471dc8b3109c1bbb:1","question":"<p>(L4, S) Как проектировать plugin platform для большого C/C++ продукта?</p>\n","answer":"<p><strong>Ответ:</strong> Минимальный versioned ABI, lifecycle protocol, packaging, compatibility tests, observability и isolation для недоверенных extensions.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L4","line":1561},{"id":"content/06_tools_build_debug/05_runtime.md:3f0551f8d2755e4f:1","question":"<p>(L4, S) Как организовать compatibility policy между host и plugins?</p>\n","answer":"<p><strong>Ответ:</strong> Определить supported ABI generations, toolchain/runtime constraints, deprecation сроки и CI matrix host/plugin combinations.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L4","line":1567},{"id":"content/06_tools_build_debug/05_runtime.md:2ed53a8178d9d4c3:1","question":"<p>(L4, D) Как расследовать production incidents, вызванные сторонним plugin'ом?</p>\n","answer":"<p><strong>Ответ:</strong> Сохранить plugin hash/version, host build, config, stack и reproduction; проверить на изолированном стенде и отключить виновный модуль.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L4","line":1573},{"id":"content/06_tools_build_debug/05_runtime.md:1992cee3b18c60d1:1","question":"<p>(L4, S) Как безопасно реализовать plugin isolation и rollback?</p>\n","answer":"<p><strong>Ответ:</strong> Process boundary ограничивает crash; проверенная предыдущая версия и контролируемая смена routing позволяют rollback без unsafe unload.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L4","line":1579},{"id":"content/06_tools_build_debug/05_runtime.md:d0f94d3d6531a629:1","question":"<p>(L4, S) Как сочетать dynamic loading, observability и crash forensics?</p>\n","answer":"<p><strong>Ответ:</strong> Логировать load/init/stop/unload, build IDs и active generation; хранить symbols всех участвовавших модулей для core analysis.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L4","line":1585},{"id":"content/06_tools_build_debug/05_runtime.md:dd605c28288f0087:1","question":"<p>(L1, T) Что такое plugin architecture?</p>\n","answer":"<p><strong>Ответ:</strong> Host предоставляет extension contract, а модули реализуют функции через этот ограниченный интерфейс.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L1","line":1596},{"id":"content/06_tools_build_debug/05_runtime.md:ccf0e3550dbae2eb:1","question":"<p>(L1, T) Какие преимущества дает plugin model?</p>\n","answer":"<p><strong>Ответ:</strong> Независимое расширение продукта и выбор функций/dependencies при запуске; выгода требует стабильного контракта.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L1","line":1602},{"id":"content/06_tools_build_debug/05_runtime.md:2a4f999c97cf32ba:1","question":"<p>(L1, T) Какие риски в plugin-based дизайне?</p>\n","answer":"<p><strong>Ответ:</strong> ABI drift, lifecycle races, dependency conflicts и crashes внутри host; in-process plugin разделяет его privileges и memory.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L1","line":1608},{"id":"content/06_tools_build_debug/05_runtime.md:10ce98a20774a68c:1","question":"<p>(L1, P) Как на базовом уровне host узнает, какие функции предоставляет plugin?</p>\n","answer":"<p><strong>Ответ:</strong> Через documented entry point, возвращающий versioned function table и capabilities; проверять size/version до доступа к полям.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L1","line":1614},{"id":"content/06_tools_build_debug/05_runtime.md:a22662bc6b914641:1","question":"<p>(L1, D) Почему plugin system усложняет поддержку?</p>\n","answer":"<p><strong>Ответ:</strong> Появляются комбинации версий, platform dependencies и ownership boundaries, которые нужно тестировать и диагностировать.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L1","line":1620},{"id":"content/06_tools_build_debug/05_runtime.md:e2b9aee30c475a76:1","question":"<p>(L2, T) Как versioning API/ABI влияет на plugin system?</p>\n","answer":"<p><strong>Ответ:</strong> API описывает source contract, ABI — binary contract; совместимый source не обязательно совместим с уже собранным plugin.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L2","line":1629},{"id":"content/06_tools_build_debug/05_runtime.md:27a0f72d334f0882:1","question":"<p>(L2, D) Почему plugin, собранный другим компилятором, может сломаться?</p>\n","answer":"<p><strong>Ответ:</strong> Могут отличаться ABI, standard library, compiler flags и calling conventions; C entry point уменьшает, но не исключает риски.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L2","line":1635},{"id":"content/06_tools_build_debug/05_runtime.md:cbecad1319d419f1:1","question":"<p>(L2, T) Как отделить extension points от внутренней реализации host'а?</p>\n","answer":"<p><strong>Ответ:</strong> Публиковать узкие callbacks/opaque handles, скрывать internal structs и не обещать стабильность внутренних symbols.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L2","line":1641},{"id":"content/06_tools_build_debug/05_runtime.md:fffb2242a2b35f27:1","question":"<p>(L2, S) Как сделать plugin contract минимальным, но достаточным?</p>\n","answer":"<p><strong>Ответ:</strong> Предоставлять необходимые операции и versioned capabilities, избегая передачи внутренних containers и неограниченных callbacks.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L2","line":1647},{"id":"content/06_tools_build_debug/05_runtime.md:e0a78dba0770c9da:1","question":"<p>(L2, D) Почему shared ownership объектов между host и plugin опасен?</p>\n","answer":"<p><strong>Ответ:</strong> Неясно, кто освобождает память и переживает unload; allocator/runtime на сторонах могут различаться.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L2","line":1653},{"id":"content/06_tools_build_debug/05_runtime.md:0bfc1d235cbd91d0:1","question":"<p>(L3, S) Как проектировать plugin lifecycle: load/init/run/stop/unload?</p>\n","answer":"<p><strong>Ответ:</strong> Явные states и rollback init failure; stop отменяет callbacks/tasks, await quiescence предшествует destroy/unload.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L3","line":1662},{"id":"content/06_tools_build_debug/05_runtime.md:ca57db70f647f626:1","question":"<p>(L3, D) Как расследовать memory/resource leaks в plugin architecture?</p>\n","answer":"<p><strong>Ответ:</strong> Сопоставлять resources с plugin generation, проверять cycles load/run/stop и outstanding handles/tasks после stop.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L3","line":1668},{"id":"content/06_tools_build_debug/05_runtime.md:bf3b84fccc5ec250:1","question":"<p>(L3, S) Как обеспечить диагностируемость ошибок plugin'ов?</p>\n","answer":"<p><strong>Ответ:</strong> Структурированные errors, plugin IDs, request correlation, lifecycle metrics и сохранение exact binary/symbols.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L3","line":1674},{"id":"content/06_tools_build_debug/05_runtime.md:f93f483801a76c25:1","question":"<p>(L3, D) Как sandbox/isolation влияют на debugging plugin'ов?</p>\n","answer":"<p><strong>Ответ:</strong> Изоляция добавляет IPC/namespace boundaries, зато позволяет отдельно наблюдать process, limits и crash artifacts.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L3","line":1680},{"id":"content/06_tools_build_debug/05_runtime.md:afb300694597716d:1","question":"<p>(L3, S) Когда нужен отдельный process boundary вместо in-process plugins?</p>\n","answer":"<p><strong>Ответ:</strong> Когда нужен fault containment, privilege separation или нельзя доверять lifecycle/ABI стороннего кода; IPC имеет цену.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L3","line":1686},{"id":"content/06_tools_build_debug/05_runtime.md:8e615f2c3008d15e:1","question":"<p>(L4, S) Как выбирать между in-process plugins, IPC modules и microservice-style extensions?</p>\n","answer":"<p><strong>Ответ:</strong> Сравнить isolation, latency, deployment independence и operational cost; boundary должен соответствовать риску и требованиям продукта.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L4","line":1695},{"id":"content/06_tools_build_debug/05_runtime.md:c096266ea5a3919f:1","question":"<p>(L4, S) Как формализовать compatibility matrix для plugins?</p>\n","answer":"<p><strong>Ответ:</strong> Таблица host ABI × plugin ABI × platform/toolchain с ожидаемым результатом load и contract tests.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L4","line":1701},{"id":"content/06_tools_build_debug/05_runtime.md:e2f484528f21d90b:1","question":"<p>(L4, D) Как triage'ить инциденты, когда host стабилен, а плагины разные и сторонние?</p>\n","answer":"<p><strong>Ответ:</strong> Группировать по plugin hash/version и symptom, собирать host context; успешность других plugins не исключает host contract bug.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L4","line":1707},{"id":"content/06_tools_build_debug/05_runtime.md:3f4d14d2f4eb0c45:1","question":"<p>(L4, S) Как проектировать upgrade path для plugin ecosystem без массовых поломок?</p>\n","answer":"<p><strong>Ответ:</strong> Capability negotiation, additive changes, compatibility adapters и период поддержки старого ABI; проверять rolling upgrade/rollback.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L4","line":1713},{"id":"content/06_tools_build_debug/05_runtime.md:6b6199931d21adbc:1","question":"<p>(L4, S) Как удержать plugin architecture от деградации в “неуправляемую платформу”?</p>\n","answer":"<p><strong>Ответ:</strong> Ограничить public contracts, назначить owners, версионировать и удалять deprecated paths по прозрачной политике.</p>\n<pre><code> **Источник:** [dlopen(3)](https://man7.org/linux/man-pages/man3/dlopen.3.html); [dlsym(3)](https://man7.org/linux/man-pages/man3/dlsym.3.html); [GCC: Code Generation Options](https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html)\n</code></pre>\n<hr />\n","group":"L4","line":1719},{"id":"content/06_tools_build_debug/05_runtime.md:b1836248fcc3564a:1","question":"<p>(L2, D) После <code>fork()</code> дочерний процесс неожиданно наследует сетевой сокет и не дает серверу корректно завершиться. Что проверять?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить fd inheritance и все references в child; CLOEXEC срабатывает при exec, а ненужный socket нужно закрыть и до него.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L2","line":1732},{"id":"content/06_tools_build_debug/05_runtime.md:d04f92c929484279:1","question":"<p>(L2, D) Многопоточное приложение иногда зависает на shutdown. Какие первые гипотезы?</p>\n","answer":"<p><strong>Ответ:</strong> Join под lock, workers без wakeup, незакрытые очереди, blocking I/O без deadline и race уничтожения ресурсов.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L2","line":1738},{"id":"content/06_tools_build_debug/05_runtime.md:dc8f451a7e01185e:1","question":"<p>(L2, D) Сервис перестает принимать новые соединения после нескольких дней работы. Какие system-level причины проверишь?</p>\n","answer":"<p><strong>Ответ:</strong> Fd leaks/limits, backlog saturation, memory pressure, CPU throttling и stuck accept loop; сохранить errno новых accept.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L2","line":1744},{"id":"content/06_tools_build_debug/05_runtime.md:5eeb0625ca59a2c5:1","question":"<p>(L2, D) <code>epoll</code>-loop грузит CPU на 100%, но полезной работы почти нет. Какие типовые причины?</p>\n","answer":"<p><strong>Ответ:</strong> Постоянный EPOLLOUT, HUP/EOF без удаления, zero timeout и EAGAIN spin; логировать events и actual I/O outcomes.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L2","line":1750},{"id":"content/06_tools_build_debug/05_runtime.md:420b1bc4afd4e5d6:1","question":"<p>(L2, D) Plugin загружается успешно, но падает при первом вызове API. Какие вероятные корни проблемы?</p>\n","answer":"<p><strong>Ответ:</strong> API version/signature, object lifetime, unresolved lazy symbols, runtime mismatch и init contract; собрать core с matching symbols.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L2","line":1756},{"id":"content/06_tools_build_debug/05_runtime.md:d9b30b8656b6da61:1","question":"<p>(L3, D) После рефакторинга часть запросов “теряется” в event loop. Как строить расследование?</p>\n","answer":"<p><strong>Ответ:</strong> Коррелировать request IDs и transitions, проверить interest masks, ET drain, ONESHOT rearm, stale generations и ownership transfer.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L3","line":1765},{"id":"content/06_tools_build_debug/05_runtime.md:1b3264db5d7e0426:1","question":"<p>(L3, D) В логах есть <code>Too many open files</code>, но локально воспроизвести не удается. Как собирать доказательства?</p>\n","answer":"<p><strong>Ответ:</strong> Периодически сохранять fd count/targets, limits и open/close attribution на production; воспроизводить длительность и traffic mix.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L3","line":1771},{"id":"content/06_tools_build_debug/05_runtime.md:99e50a56c6da778b:1","question":"<p>(L3, D) Child process иногда зависает сразу после <code>fork()</code> и до <code>exec()</code>. Почему это особенно подозрительно в multithreaded приложении?</p>\n","answer":"<p><strong>Ответ:</strong> Child мог унаследовать locked runtime state без owner thread; искать malloc/logging/locks между fork и exec.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L3","line":1777},{"id":"content/06_tools_build_debug/05_runtime.md:7d40973fbd5fbe64:1","question":"<p>(L3, D) После hot reload plugin'а сервис нестабилен. Какие классы ошибок ищешь в первую очередь?</p>\n","answer":"<p><strong>Ответ:</strong> Stale callbacks/function pointers, unfinished workers, shared objects, allocator mismatch и неверную ABI negotiation новой generation.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L3","line":1783},{"id":"content/06_tools_build_debug/05_runtime.md:03595f187d951852:1","question":"<p>(L3, D) Производительность резко падает при увеличении числа потоков. Как отличить scheduler/lock contention/fd event issues?</p>\n","answer":"<p><strong>Ответ:</strong> Сравнить runnable/wait states, lock hold/wait, loop lag и queue depth; затем изолировать число workers и shards.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L3","line":1789},{"id":"content/06_tools_build_debug/05_runtime.md:3e4b2bf2f40f15e5:1","question":"<p>(L4, S) Как спроектировать runtime architecture Linux-сервиса: процессы, потоки, сигналы, event loop, plugins?</p>\n","answer":"<p><strong>Ответ:</strong> Определить owners и process boundaries, bounded worker/I/O paths, signal control plane, shutdown protocol и plugin isolation requirements.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L4","line":1798},{"id":"content/06_tools_build_debug/05_runtime.md:05e2623e6c020de5:1","question":"<p>(L4, S) Какие invariants и ownership rules обязательно документировать в system-level C/C++ коде?</p>\n","answer":"<p><strong>Ответ:</strong> Кто создаёт/закрывает ресурс, кто может его использовать, synchronization order, deadlines, cancellation и момент окончательного освобождения.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L4","line":1804},{"id":"content/06_tools_build_debug/05_runtime.md:00a2bf8c48e5f4a7:1","question":"<p>(L4, S) Как уменьшить число production incidents, связанных с fd lifecycle, signals и concurrency?</p>\n","answer":"<p><strong>Ответ:</strong> RAII, atomic CLOEXEC creation, owner-based event loops, signal policy и tests lifecycle under failure/stress.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L4","line":1810},{"id":"content/06_tools_build_debug/05_runtime.md:9233e9971f5534f2:1","question":"<p>(L4, S) Как стандартизировать подход к graceful shutdown, crash handling и resource cleanup?</p>\n","answer":"<p><strong>Ответ:</strong> Общий state machine shutdown с deadlines; crash artifacts сохраняет supervision, unsafe handlers не выполняют сложный cleanup.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html\">dlopen(3)</a>; <a href=\"https://man7.org/linux/man-pages/man3/dlsym.3.html\">dlsym(3)</a>; <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html\">GCC: Code Generation Options</a></p>\n","group":"L4","line":1816},{"id":"content/06_tools_build_debug/05_runtime.md:4470cf6be32b4746:1","question":"<p>(L4, S) Как выстроить инженерную культуру, где runtime/system-level ошибки расследуются доказательно, а не “по ощущениям”?</p>\n","answer":"<p><strong>Ответ:</strong> Сохранять факты: errors, timestamps, build IDs, stacks и resource trends; каждую гипотезу проверять воспроизводимым экспериментом.</p>\n<pre><code> **Источник:** [dlopen(3)](https://man7.org/linux/man-pages/man3/dlopen.3.html); [dlsym(3)](https://man7.org/linux/man-pages/man3/dlsym.3.html); [GCC: Code Generation Options](https://gcc.gnu.org/onlinedocs/gcc/Code-Gen-Options.html)\n</code></pre>\n<hr />\n","group":"L4","line":1822}];
